import{_ as e,o as i,c as s,a2 as l}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Clasificación y Simbiosis de las Razas Alienígenas","description":"","frontmatter":{},"headers":[],"relativePath":"es/0052-异族分类与共生.md","filePath":"es/0052-异族分类与共生.md"}'),n={name:"es/0052-异族分类与共生.md"};function r(o,a,t,c,d,u){return i(),s("div",null,[...a[0]||(a[0]=[l('<h1 id="clasificacion-y-simbiosis-de-las-razas-alienigenas" tabindex="-1">Clasificación y Simbiosis de las Razas Alienígenas <a class="header-anchor" href="#clasificacion-y-simbiosis-de-las-razas-alienigenas" aria-label="Permalink to &quot;Clasificación y Simbiosis de las Razas Alienígenas&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>52</td></tr><tr><td>Módulo</td><td>Razas y Formas de Vida</td></tr><tr><td>Palabras clave</td><td>Razas alienígenas, estándares de clasificación, modos simbióticos, respeto cultural, adaptación racial</td></tr></tbody></table><h2 id="i-definicion-del-concepto-de-razas-alienigenas" tabindex="-1">I. Definición del Concepto de Razas Alienígenas <a class="header-anchor" href="#i-definicion-del-concepto-de-razas-alienigenas" aria-label="Permalink to &quot;I. Definición del Concepto de Razas Alienígenas&quot;">​</a></h2><p>En el contexto de la Civilización Simbiótica del Ancla, las &quot;razas alienígenas&quot; (Yì Zú) son un concepto relativo a la raza humana, que designa a todas las razas distintas de la raza humana. Debe subrayarse especialmente que el concepto de &quot;razas alienígenas&quot; tiene únicamente significado taxonómico y no conlleva absolutamente ningún juicio de valor ni connotación discriminatoria. En el marco de la Constitución Simbiótica, las razas alienígenas y la raza humana gozan de un estatus jurídico y unos derechos fundamentales totalmente iguales.</p><p>El propósito de proponer el concepto de razas alienígenas es comprender y estudiar sistemáticamente las diversas formas de vida distintas de la raza humana, proporcionando una base científica para formular políticas simbióticas específicas, medidas de protección cultural y planes de adaptación racial — en lugar de tratar a las razas alienígenas como &quot;otros&quot; o &quot;extraños&quot;.</p><h2 id="ii-estandares-de-clasificacion-de-las-razas-alienigenas" tabindex="-1">II. Estándares de Clasificación de las Razas Alienígenas <a class="header-anchor" href="#ii-estandares-de-clasificacion-de-las-razas-alienigenas" aria-label="Permalink to &quot;II. Estándares de Clasificación de las Razas Alienígenas&quot;">​</a></h2><p>Las razas alienígenas del Universo Hengyuan se clasifican según múltiples dimensiones, formando un sistema de clasificación multidimensional:</p><h3 id="i-clasificacion-por-genealogia-de-vida" tabindex="-1">(I) Clasificación por genealogía de vida <a class="header-anchor" href="#i-clasificacion-por-genealogia-de-vida" aria-label="Permalink to &quot;(I) Clasificación por genealogía de vida&quot;">​</a></h3><p>Es el estándar de clasificación más básico; véase <em>50-万族谱系总览</em> para más detalles:</p><table tabindex="0"><thead><tr><th>Genealogía</th><th>Razas alienígenas incluidas</th></tr></thead><tbody><tr><td>Razas materiales de base carbónica</td><td>Shòu Zú (Raza Bestial), Lín Zú (Raza Escamada), Yǔ Zú (Raza Emplumada), Mù Zú (Raza Vegetal), etc.</td></tr><tr><td>Razas de energía condensada</td><td>Líng Zú (Raza Espiritual), Huǒ Zú (Raza de Fuego), Shuǐ Zú (Raza de Agua), Fēng Zú (Raza de Viento), Léi Zú (Raza de Trueno), etc.</td></tr><tr><td>Razas de construcción mecánica</td><td>Jī Zú (Raza Mecánica), Shù Zú (Raza Numérica), Jīng Zú (Raza de Cristal), etc.</td></tr><tr><td>Razas de conciencia-información</td><td>Mèng Zú (Raza de Sueño), Yǐng Zú (Raza de Sombra), Niàn Zú (Raza Mental), Hún Zú (Raza de Alma), etc.</td></tr><tr><td>Razas mixtas-variantes</td><td>Bàn Shòu Zú (Raza Semibestial), Yāo Líng Zú (Raza Demoníaco-Espiritual), Rén Jī Zú (Raza Humano-Mecánica), Shuānghún Tǐ (Entidad de Alma Dual), etc.</td></tr></tbody></table><h3 id="ii-clasificacion-por-grado-de-civilizacion" tabindex="-1">(II) Clasificación por grado de civilización <a class="header-anchor" href="#ii-clasificacion-por-grado-de-civilizacion" aria-label="Permalink to &quot;(II) Clasificación por grado de civilización&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nivel</th><th>Nombre</th><th>Características</th><th>Razas representativas</th></tr></thead><tbody><tr><td>Primer nivel</td><td>Razas de civilización primitiva</td><td>Aún no han establecido instituciones sociales estables, sobreviven en forma tribal</td><td>Algunas ramas de la Shòu Zú, Mù Zú primitiva</td></tr><tr><td>Segundo nivel</td><td>Razas de civilización clásica</td><td>Han establecido instituciones estatales y cultura clásica, en la etapa agrícola o artesanal</td><td>Algunas Lín Zú, Yǔ Zú</td></tr><tr><td>Tercer nivel</td><td>Razas de civilización científica y tecnológica</td><td>Han desarrollado civilización tecnológica, entrando en la era industrial o de la información</td><td>Jī Zú, Shù Zú, algunas Rén Zú</td></tr><tr><td>Cuarto nivel</td><td>Razas de civilización de cultivo</td><td>Toman el sistema de cultivo como forma civilizacional central, con cultivadores dominando la sociedad</td><td>Líng Zú, Lóng Zú, algunas Rén Zú</td></tr><tr><td>Quinto nivel</td><td>Razas de civilización simbiótica</td><td>Se han unido a la Civilización Simbiótica del Ancla y aceptado el concepto y las instituciones simbióticas</td><td>Todas las razas que se han unido a la civilización simbiótica</td></tr></tbody></table><h3 id="iii-clasificacion-por-adaptabilidad-ambiental" tabindex="-1">(III) Clasificación por adaptabilidad ambiental <a class="header-anchor" href="#iii-clasificacion-por-adaptabilidad-ambiental" aria-label="Permalink to &quot;(III) Clasificación por adaptabilidad ambiental&quot;">​</a></h3><ul><li><strong>Razas terrestres</strong>: razas adaptadas a entornos terrestres, como la Rén Zú, la Shòu Zú y la Jī Zú.</li><li><strong>Razas acuáticas</strong>: razas adaptadas a entornos acuáticos, como la Lín Zú, la Shuǐ Zú y algunas razas mixtas.</li><li><strong>Razas aéreas</strong>: razas adaptadas a entornos de gran altitud o de vuelo, como la Yǔ Zú y la Fēng Zú.</li><li><strong>Razas ígneas</strong>: razas adaptadas a entornos de alta temperatura, como la Huǒ Zú y algunas Lín Zú.</li><li><strong>Razas glaciares</strong>: razas adaptadas a entornos de baja temperatura, como la Bīng Zú y algunas Mù Zú.</li><li><strong>Razas energéticas</strong>: razas adaptadas a entornos de alta concentración de energía, como la Líng Zú y la Léi Zú.</li><li><strong>Razas espaciales</strong>: razas adaptadas a fisuras espaciales o entornos de espacio extraño, como la Yǐng Zú y algunas Niàn Zú.</li></ul><h3 id="iv-clasificacion-por-forma-social" tabindex="-1">(IV) Clasificación por forma social <a class="header-anchor" href="#iv-clasificacion-por-forma-social" aria-label="Permalink to &quot;(IV) Clasificación por forma social&quot;">​</a></h3><ul><li><strong>Razas individualistas</strong>: enfatizan la independencia y libertad individuales, con estructuras sociales laxas, como algunas Líng Zú y Yǐng Zú.</li><li><strong>Razas colectivistas</strong>: enfatizan los intereses colectivos y la colaboración, con estructuras sociales estrechas, como la Yǐ Zú (Raza de Hormigas), la Fēng Zú (Raza de Abejas) y algunas Jī Zú.</li><li><strong>Razas familiaristas</strong>: toman las familias consanguíneas como unidad social básica, como la Lóng Zú y algunas Shòu Zú.</li><li><strong>Razas religiosas</strong>: toman la creencia religiosa como núcleo de cohesión social, como algunas razas rituales.</li><li><strong>Razas tecnocráticas</strong>: toman el desarrollo tecnológico como objetivo social central, como la Jī Zú y la Shù Zú.</li></ul><h2 id="iii-principales-modos-simbioticos-de-las-razas-alienigenas" tabindex="-1">III. Principales Modos Simbióticos de las Razas Alienígenas <a class="header-anchor" href="#iii-principales-modos-simbioticos-de-las-razas-alienigenas" aria-label="Permalink to &quot;III. Principales Modos Simbióticos de las Razas Alienígenas&quot;">​</a></h2><p>Para diferentes tipos de razas alienígenas, la Civilización Simbiótica del Ancla adopta modos simbióticos diferenciados:</p><h3 id="i-modos-simbioticos-de-las-razas-materiales-de-base-carbonica" tabindex="-1">(I) Modos simbióticos de las razas materiales de base carbónica <a class="header-anchor" href="#i-modos-simbioticos-de-las-razas-materiales-de-base-carbonica" aria-label="Permalink to &quot;(I) Modos simbióticos de las razas materiales de base carbónica&quot;">​</a></h3><ul><li><strong>Shòu Zú (Raza Bestial)</strong>: aprovechar las ventajas físicas y sensoriales de la raza bestial para asumir papeles importantes en la exploración de recursos, la protección de la seguridad y la vigilancia ambiental. Al mismo tiempo, proteger la cultura tribal y las tradiciones salvajes de la raza bestial y prohibir la domesticación forzada.</li><li><strong>Lín Zú (Raza Escamada)</strong>: aprovechar la adaptabilidad acuática de la raza escamada para asumir papeles en el desarrollo de recursos acuáticos, la construcción submarina y la protección ecológica acuática. Como rama poderosa de la raza escamada, la Lóng Zú (Raza del Dragón) desempeña un papel importante en el cultivo avanzado y la custodia civilizacional.</li><li><strong>Yǔ Zú (Raza Emplumada)</strong>: aprovechar la capacidad de vuelo de la raza emplumada para asumir papeles en el tráfico aéreo, la vigilancia meteorológica y la patrulla aérea. Proteger los hábitats de gran altitud y las rutas migratorias de la raza emplumada.</li><li><strong>Mù Zú (Raza Vegetal)</strong>: aprovechar la capacidad de simbiosis natural de la raza vegetal para asumir papeles en la protección ecológica, la gobernanza ambiental, el desarrollo de recursos vegetales y la medicina curativa. La larga vida de la raza vegetal la convierte en una fuerza importante en la transmisión histórica y la planificación a largo plazo.</li></ul><h3 id="ii-modos-simbioticos-de-las-razas-de-energia-condensada" tabindex="-1">(II) Modos simbióticos de las razas de energía condensada <a class="header-anchor" href="#ii-modos-simbioticos-de-las-razas-de-energia-condensada" aria-label="Permalink to &quot;(II) Modos simbióticos de las razas de energía condensada&quot;">​</a></h3><ul><li><strong>Líng Zú (Raza Espiritual)</strong>: aprovechar la manipulación de la energía y el talento de cultivo de la raza espiritual para asumir papeles centrales en la investigación de sistemas de cultivo, la regulación de la energía y la guía del cultivo avanzado. La raza espiritual es una importante investigadora y transmisora de los Trescientos Sistemas de Cultivo Originarios.</li><li><strong>Razas elementales (Huǒ/Shuǐ/Fēng/Léi)</strong>: aprovechar las capacidades de manipulación elemental de cada raza para asumir papeles en el desarrollo energético, la gobernanza ambiental, la producción industrial y la prevención y control de desastres. Al mismo tiempo, establecer sistemas de gestión de la seguridad de la energía elemental para evitar que la pérdida de control de la energía cause daños.</li></ul><h3 id="iii-modos-simbioticos-de-las-razas-de-construccion-mecanica" tabindex="-1">(III) Modos simbióticos de las razas de construcción mecánica <a class="header-anchor" href="#iii-modos-simbioticos-de-las-razas-de-construccion-mecanica" aria-label="Permalink to &quot;(III) Modos simbióticos de las razas de construcción mecánica&quot;">​</a></h3><ul><li><strong>Jī Zú (Raza Mecánica)</strong>: aprovechar la capacidad de cálculo y la defensa física de la raza mecánica para asumir papeles centrales en la construcción de infraestructuras, la producción industrial, la protección de la seguridad y la exploración del espacio profundo. La raza mecánica es una importante constructora del hardware y las infraestructuras del Ancla.</li><li><strong>Shù Zú (Raza Numérica)</strong>: aprovechar las capacidades de procesamiento de datos y manipulación de la información de la raza numérica para asumir papeles centrales en la construcción informacional, el análisis de datos, la seguridad de redes y la inteligencia artificial. La raza numérica es una importante mantenedora de la tecnología de comunicación transplanar y de la red simbiótica.</li><li><strong>Jīng Zú (Raza de Cristal)</strong>: aprovechar la capacidad de almacenamiento y transformación de la energía de la raza de cristal para asumir papeles en las reservas de energía, la estandarización de la energía y la transmisión de la energía.</li></ul><h3 id="iv-modos-simbioticos-de-las-razas-de-conciencia-informacion" tabindex="-1">(IV) Modos simbióticos de las razas de conciencia-información <a class="header-anchor" href="#iv-modos-simbioticos-de-las-razas-de-conciencia-informacion" aria-label="Permalink to &quot;(IV) Modos simbióticos de las razas de conciencia-información&quot;">​</a></h3><ul><li><strong>Mèng Zú (Raza de Sueño)</strong>: aprovechar la capacidad de comunicación consciente de la raza de sueño para asumir papeles en la terapia psicológica, la investigación de la conciencia, la comunicación interracial y el intercambio cultural. Establecer sistemas de gestión del espacio onírico para prevenir la intrusión consciente y la violación de la privacidad.</li><li><strong>Yǐng Zú (Raza de Sombra)</strong>: aprovechar las capacidades de ocultación y sigilo de la raza de sombra para asumir papeles en el reconocimiento de seguridad, la recolección de inteligencia y las misiones especiales. Al mismo tiempo, establecer normas de conducta para la raza de sombra para evitar que la capacidad de invisibilidad se use para actividades ilegales.</li><li><strong>Niàn Zú (Raza Mental)</strong>: aprovechar la fuerza mental y la capacidad de manipulación telequinética de la raza mental para asumir papeles en la investigación de la evolución de la conciencia, la terapia mental y la guía del cultivo avanzado. Establecer normas para el uso de la fuerza mental para prevenir el control mental y la manipulación de la conciencia.</li></ul><h3 id="v-modos-simbioticos-de-las-razas-mixtas-variantes" tabindex="-1">(V) Modos simbióticos de las razas mixtas-variantes <a class="header-anchor" href="#v-modos-simbioticos-de-las-razas-mixtas-variantes" aria-label="Permalink to &quot;(V) Modos simbióticos de las razas mixtas-variantes&quot;">​</a></h3><p>Debido a sus formas de vida especiales, las razas mixtas-variantes requieren políticas simbióticas más refinadas:</p><ul><li>Establecer un sistema de registro y certificación de identidad para las razas mixtas-variantes para confirmar su estatus legal.</li><li>Proporcionar servicios públicos adaptados (médicos, educativos, de vivienda, etc.) para las diferentes formas mixtas.</li><li>Oponerse a la discriminación y exclusión de las razas mixtas-variantes y promover la aceptación social.</li><li>Para formas mixtas especiales como la Shuānghún Tǐ (Entidad de Alma Dual), aplicar el <em>58-双魂伦理准则</em> para una gestión especializada.</li></ul><h2 id="iv-proteccion-de-las-culturas-de-las-razas-alienigenas" tabindex="-1">IV. Protección de las Culturas de las Razas Alienígenas <a class="header-anchor" href="#iv-proteccion-de-las-culturas-de-las-razas-alienigenas" aria-label="Permalink to &quot;IV. Protección de las Culturas de las Razas Alienígenas&quot;">​</a></h2><p>Las culturas de las razas alienígenas son una parte importante de la diversidad cultural de las Diez Mil Razas. El Estado adopta las siguientes medidas para proteger las culturas de las razas alienígenas:</p><ol><li><strong>Censo y registro culturales</strong>: realizar censos y registros sistemáticos de la cultura de cada raza, establecer un archivo de las culturas de las Diez Mil Razas y prevenir la pérdida cultural.</li><li><strong>Protección de lenguas y escrituras</strong>: proteger las lenguas y escrituras de cada raza, apoyar la enseñanza y el uso de las lenguas y escrituras de las razas alienígenas y establecer un sistema de servicios públicos multilingüe.</li><li><strong>Protección de festividades tradicionales</strong>: respetar las festividades tradicionales y las costumbres de cada raza, y organizar los días festivos públicos considerando las festividades importantes de cada raza.</li><li><strong>Apoyo a la transmisión cultural</strong>: apoyar la formación de transmisores culturales de cada raza y la organización de actividades culturales, proporcionando apoyo financiero y de espacios.</li><li><strong>Promoción del intercambio cultural</strong>: organizar regularmente festivales culturales de las Diez Mil Razas, exposiciones culturales y otras actividades para promover el intercambio cultural y el aprendizaje mutuo entre todas las razas.</li><li><strong>Protección de la propiedad intelectual cultural</strong>: proteger la propiedad intelectual de las culturas tradicionales de cada raza y prevenir el saqueo cultural y la comercialización inapropiada.</li></ol><h2 id="v-gobernanza-de-los-asuntos-de-las-razas-alienigenas" tabindex="-1">V. Gobernanza de los Asuntos de las Razas Alienígenas <a class="header-anchor" href="#v-gobernanza-de-los-asuntos-de-las-razas-alienigenas" aria-label="Permalink to &quot;V. Gobernanza de los Asuntos de las Razas Alienígenas&quot;">​</a></h2><p>El Estado establece el Ministerio de Asuntos Raciales, encargado específicamente de la gobernanza y coordinación de los asuntos de las razas alienígenas:</p><ul><li><strong>Sistema de representantes raciales</strong>: las instituciones de gobernanza de todos los niveles cuentan proporcionalmente con representantes de las razas alienígenas para garantizar la voz de estas razas.</li><li><strong>Políticas de adaptación racial</strong>: formular políticas de servicios públicos diferenciadas según las características fisiológicas y las necesidades culturales de las diferentes razas.</li><li><strong>Mediación de disputas raciales</strong>: establecer un mecanismo de mediación de disputas raciales para resolver oportunamente las contradicciones y conflictos raciales.</li><li><strong>Asistencia legal a las razas alienígenas</strong>: proporcionar asistencia legal a las razas alienígenas para asegurar que reciban un trato igualitario en los procesos judiciales.</li><li><strong>Apoyo al desarrollo de las razas alienígenas</strong>: brindar apoyo especial a las razas relativamente subdesarrolladas para ayudarlas a elevar su nivel de civilización y calidad de vida.</li></ul><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>Las razas alienígenas no son los &quot;otros&quot; de la raza humana, sino miembros iguales de la gran familia de la simbiosis de las Diez Mil Razas. Al establecer un sistema de clasificación multidimensional, adoptar modos simbióticos diferenciados, proteger las culturas de las razas alienígenas y mejorar la gobernanza de sus asuntos, la Civilización Simbiótica del Ancla garantiza que cada raza alienígena pueda encontrar una posición adecuada en el sistema simbiótico, ejercer sus ventajas únicas y evolucionar y prosperar junto con las demás razas.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>50-万族谱系总览 (Panorama de la Genealogía de las Diez Mil Razas)</li><li>51-人族定位与特质 (Posicionamiento y Rasgos de la Raza Humana)</li><li>53-奇特生命识别标准 (Estándares de Identificación de la Vida Anómala)</li><li>05-万族共进基本纲领 (Programa Básico para el Avance Conjunto de las Diez Mil Razas)</li></ul>',39)])])}const g=e(n,[["render",r]]);export{p as __pageData,g as default};
